import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {createRequire} from 'node:module';import{hash,json}from'./bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-oral-recall-native',sf=stage+'/SOURCE_CANDIDATE.json',source=json(sf),site=source.atlas,vf=stage+'/VERIFICATION_FULL_NATIVE.json';
const pin=p=>({path:p,sha256:hash(p)}),save=(p,x)=>fs.writeFileSync(p,JSON.stringify(x,null,2)+'\n',{flag:'wx'});
assert.equal(hash(sf),'ebe7c8272ccf51fdc9c698761513b9fb5bfae7c3184255d2ecfd90f27badb785');assert.deepEqual(json('CURRENT_CHECKPOINT.json').activeWork.current.activeExecutionSessions,[]);
const prior=json(stage+'/VERIFICATION_SUMMARY.json');assert(prior.passingForStatedScope&&prior.source.sha256===hash(sf));for(const r of Object.values(prior.checks)){assert.equal(hash(r.path),r.sha256);assert(json(r.path).passing);}
for(const r of [...source.sourceRows,...source.publicRows])assert.equal(hash(site+'/'+r.path),r.sha256,r.path);
const checks=Object.fromEntries(['types','build'].map(n=>{const p=stage+'/checks/'+n+'-'+(n==='types'?2:1)+'/RESULT.json';assert(json(p).passing);assert.equal(json(p).source.sha256,hash(sf));return[n,pin(p)];}));
const types=json(stage+'/FULL_TYPE_RESULT_native_2.json');assert(types.fullProjectTypes&&types.diagnosticCount===0);for(const r of types.sourceFiles)assert.equal(hash(r.path),r.sha256,r.path);
const ts=createRequire(site+'/package.json')('typescript'),cfg=ts.readConfigFile(site+'/tsconfig.json',ts.sys.readFile);assert(!cfg.error);const parsed=ts.parseJsonConfigFileContent(cfg.config,ts.sys,site);assert.equal(parsed.errors.length,0);assert.deepEqual(parsed.fileNames.map(p=>path.resolve(p).toLowerCase()).sort(),types.roots.map(p=>path.resolve(p).toLowerCase()).sort());
const files=[];function walk(dir){for(const e of fs.readdirSync(dir,{withFileTypes:true})){assert(!e.isSymbolicLink());const p=dir+'/'+e.name;if(e.isDirectory())walk(p);else{assert(e.isFile());files.push({path:path.relative(site,p).replaceAll('\\','/'),bytes:fs.statSync(p).size,sha256:hash(p)});}}}walk(site+'/dist');assert(files.length>500);
save(stage+'/BUILD_ARTIFACTS.json',{at:new Date().toISOString(),root:site,source:pin(sf),files,localOnly:true});
save(vf,{at:new Date().toISOString(),passingForStatedScope:true,source:pin(sf),priorFocusedVerification:pin(stage+'/VERIFICATION_SUMMARY.json'),checks,fullConfiguredTypes:{...pin(stage+'/FULL_TYPE_RESULT_native_2.json'),roots:types.roots.length,files:types.sourceFiles.length,diagnostics:0},build:pin(stage+'/BUILD_ARTIFACTS.json'),buildArtifacts:files.length,sourceAndPublicAssetsExact:true,outcomes:prior.outcomes,clinicalApproval:false,websiteImported:false,normalPreviewChanged:false,wholeStockSuitePassing:false});
const build=json(checks.build.path);assert(build.run.process.terminalObserved&&build.run.process.exitCode===0);
save(stage+'/BUILD_VERIFIED.json',{at:new Date().toISOString(),passing:true,fullNativeBuildPassed:true,source:pin(sf),run:build,artifacts:pin(stage+'/BUILD_ARTIFACTS.json'),verification:pin(vf)});
console.log(JSON.stringify({source:pin(sf),verification:pin(vf),artifacts:files.length,head:source.head}));
